// Package textdiff computes unified diffs between two pieces of text.
package textdiff

import (
	"fmt"

	udiff "github.com/aymanbagabas/go-udiff"
)

// DefaultContext is the number of unchanged lines shown around each hunk.
const DefaultContext = udiff.DefaultContextLines

// Unified returns a unified diff turning want into got, labelled with
// wantName and gotName. It returns "" if the inputs are identical.
func Unified(wantName, gotName, want, got string) string {
	return udiff.Unified(wantName, gotName, want, got)
}

// UnifiedContext is like Unified but shows context lines of surrounding
// unchanged text around each hunk.
func UnifiedContext(wantName, gotName, want, got string, context int) (string, error) {
	if context < 0 {
		return "", fmt.Errorf("textdiff: negative context %d", context)
	}
	edits := udiff.Lines(want, got)
	return udiff.ToUnified(wantName, gotName, want, edits, context)
}

// TB is the subset of testing.TB used by Check.
type TB interface {
	Helper()
	Errorf(format string, args ...any)
}

// Check reports a test error with a unified diff if got differs from want.
// It returns true if they are equal.
func Check(t TB, want, got string) bool {
	t.Helper()
	if d := Unified("want", "got", want, got); d != "" {
		t.Errorf("mismatch (-want +got):\n%s", d)
		return false
	}
	return true
}
EOF
cat > textdiff/textdiff_test.go <<'EOF'
package textdiff

import (
	"fmt"
	"testing"
)

func TestUnifiedEqual(t *testing.T) {
	if d := Unified("a", "b", "same\n", "same\n"); d != "" {
		t.Fatalf("expected empty diff, got:\n%s", d)
	}
}

func TestUnified(t *testing.T) {
	want := "one\ntwo\nthree\n"
	got := "one\n2\nthree\n"
	exp := `--- a
+++ b
@@ -1,3 +1,3 @@
 one
-two
+2
 three
`
	if d := Unified("a", "b", want, got); d != exp {
		t.Errorf("Unified:\n%s\nwant:\n%s", d, exp)
	}
}

func TestUnifiedNoTrailingNewline(t *testing.T) {
	d := Unified("a", "b", "x", "y")
	exp := `--- a
+++ b
@@ -1 +1 @@
-x
\ No newline at end of file
+y
\ No newline at end of file
`
	if d != exp {
		t.Errorf("Unified:\n%s\nwant:\n%s", d, exp)
	}
}

func TestUnifiedContext(t *testing.T) {
	want := "1\n2\n3\n4\n5\n"
	got := "1\n2\nX\n4\n5\n"
	d, err := UnifiedContext("a", "b", want, got, 0)
	if err != nil {
		t.Fatal(err)
	}
	exp := "--- a\n+++ b\n@@ -3 +3 @@\n-3\n+X\n"
	if d != exp {
		t.Errorf("UnifiedContext:\n%s\nwant:\n%s", d, exp)
	}
	if _, err := UnifiedContext("a", "b", want, got, -1); err == nil {
		t.Error("expected error for negative context")
	}
}

type fakeTB struct{ msgs []string }

func (f *fakeTB) Helper() {}
func (f *fakeTB) Errorf(format string, args ...any) {
	f.msgs = append(f.msgs, fmt.Sprintf(format, args...))
}

func TestCheck(t *testing.T) {
	var f fakeTB
	if !Check(&f, "a\n", "a\n") || len(f.msgs) != 0 {
		t.Errorf("Check on equal input reported %v", f.msgs)
	}
	if Check(&f, "a\n", "b\n") || len(f.msgs) != 1 {
		t.Errorf("Check on different input: msgs=%v", f.msgs)
	}
}
EOF
